mapper.select:
SELECT DISTINCT a.id, a.uuid, a.title, a.slug, a.summary, u.nickname AS authorNickname, a.view_count AS viewCount, a.like_count AS likeCount, a.published_at AS publishedAt FROM articles a JOIN article_tags at ON a.id = at.article_id JOIN users u ON a.author_id = u.id WHERE at.tag_id IN
#{tagId}
AND a.uuid != #{excludeUuid}::uuid AND a.status = 'PUBLISHED' ORDER BY a.view_count DESC LIMIT #{limit}

SELECT at.article_id AS articleId, t.name AS tagName FROM article_tags at JOIN tags t ON at.tag_id = t.id WHERE at.article_id IN
#{articleId}
ORDER BY at.article_id, t.name
